{
  "id": "add_persona_image",
  "name": "Add a photograph to a character",
  "description": "Copy a reference photograph beside the sheet. It is kept with the character, travels with an export, and can be read by a vision model to fill the appearance. The roleplay model never sees it.",
  "inputSchema": {
    "type": "object",
    "additionalProperties": false,
    "properties": {
      "persona_id": {
        "type": "string",
        "default": "",
        "title": "Character",
        "maxLength": 80,
        "pattern": "^$|^[a-z0-9][a-z0-9-]{0,79}$"
      },
      "image": {
        "type": "string",
        "default": "",
        "title": "Image (PNG, JPEG, WebP, BMP)",
        "maxLength": 1000,
        "x-cy-kind": "Image"
      },
      "role": {
        "type": "string",
        "default": "reference",
        "title": "What it shows",
        "enum": [
          "portrait",
          "full_body",
          "outfit",
          "detail",
          "expression",
          "setting",
          "reference"
        ]
      },
      "caption": {
        "type": "string",
        "default": "",
        "title": "Caption",
        "maxLength": 600
      }
    },
    "required": [
      "persona_id",
      "image"
    ]
  },
  "outputSchema": {
    "type": "object",
    "additionalProperties": true,
    "properties": {
      "persona": {
        "type": "object",
        "additionalProperties": false,
        "default": {},
        "properties": {
          "format": {
            "type": "string",
            "default": "cytools-personarp-persona"
          },
          "schemaVersion": {
            "type": "integer",
            "default": 1
          },
          "id": {
            "type": "string",
            "maxLength": 80,
            "default": "",
            "title": "Identifier"
          },
          "name": {
            "type": "string",
            "maxLength": 120,
            "default": "New character",
            "title": "Character name"
          },
          "aliases": {
            "type": "array",
            "default": [],
            "title": "Other names",
            "maxItems": 64,
            "items": {
              "type": "string",
              "maxLength": 120
            }
          },
          "pronouns": {
            "type": "string",
            "maxLength": 60,
            "default": "",
            "title": "Pronouns"
          },
          "age": {
            "type": "string",
            "maxLength": 80,
            "default": "",
            "title": "Age"
          },
          "species": {
            "type": "string",
            "maxLength": 120,
            "default": "",
            "title": "Species or kind"
          },
          "world_id": {
            "type": "string",
            "maxLength": 80,
            "default": "",
            "title": "World",
            "description": "The shared lore this character belongs to."
          },
          "summary": {
            "type": "string",
            "maxLength": 1200,
            "default": "",
            "title": "Pitch",
            "description": "Two lines that place the character."
          },
          "tags": {
            "type": "array",
            "default": [],
            "title": "Tags",
            "maxItems": 64,
            "items": {
              "type": "string",
              "maxLength": 60
            }
          },
          "enabled": {
            "type": "boolean",
            "default": true,
            "title": "Roleplay this sheet"
          },
          "appearance": {
            "type": "object",
            "title": "Appearance",
            "default": {},
            "additionalProperties": false,
            "properties": {
              "summary": {
                "type": "string",
                "maxLength": 1200,
                "default": "",
                "title": "In one look"
              },
              "build": {
                "type": "string",
                "maxLength": 300,
                "default": "",
                "title": "Build and height"
              },
              "face": {
                "type": "string",
                "maxLength": 600,
                "default": "",
                "title": "Face"
              },
              "hair": {
                "type": "string",
                "maxLength": 300,
                "default": "",
                "title": "Hair"
              },
              "eyes": {
                "type": "string",
                "maxLength": 300,
                "default": "",
                "title": "Eyes"
              },
              "skin": {
                "type": "string",
                "maxLength": 300,
                "default": "",
                "title": "Skin"
              },
              "outfit": {
                "type": "string",
                "maxLength": 800,
                "default": "",
                "title": "Usual outfit"
              },
              "marks": {
                "type": "string",
                "maxLength": 600,
                "default": "",
                "title": "Scars, tattoos, distinguishing marks"
              },
              "accessories": {
                "type": "string",
                "maxLength": 600,
                "default": "",
                "title": "Carried items and accessories"
              },
              "age_reading": {
                "type": "string",
                "maxLength": 120,
                "default": "",
                "title": "Apparent age"
              },
              "visual_tags": {
                "type": "array",
                "default": [],
                "title": "Visual tags",
                "maxItems": 64,
                "items": {
                  "type": "string",
                  "maxLength": 80
                },
                "description": "Short tags reused verbatim in image prompts, for consistency."
              },
              "negative_tags": {
                "type": "array",
                "default": [],
                "title": "Never depict",
                "maxItems": 64,
                "items": {
                  "type": "string",
                  "maxLength": 80
                }
              },
              "style_reference": {
                "type": "string",
                "maxLength": 400,
                "default": "",
                "title": "Rendering style",
                "description": "Art direction: medium, palette, lens, grain."
              }
            },
            "description": "Everything a renderer needs to draw this character the same way twice."
          },
          "references": {
            "type": "array",
            "default": [],
            "maxItems": 32,
            "title": "Reference photographs",
            "items": {
              "type": "object",
              "title": "Reference photograph",
              "default": {},
              "additionalProperties": false,
              "properties": {
                "file": {
                  "type": "string",
                  "maxLength": 1000,
                  "default": "",
                  "title": "File"
                },
                "role": {
                  "type": "string",
                  "default": "reference",
                  "title": "What it shows",
                  "enum": [
                    "portrait",
                    "full_body",
                    "outfit",
                    "detail",
                    "expression",
                    "setting",
                    "reference"
                  ]
                },
                "caption": {
                  "type": "string",
                  "maxLength": 600,
                  "default": "",
                  "title": "Caption"
                },
                "sha256": {
                  "type": "string",
                  "maxLength": 64,
                  "default": "",
                  "title": "Fingerprint"
                },
                "width": {
                  "type": "integer",
                  "minimum": 0,
                  "default": 0
                },
                "height": {
                  "type": "integer",
                  "minimum": 0,
                  "default": 0
                },
                "bytes": {
                  "type": "integer",
                  "minimum": 0,
                  "default": 0
                },
                "mimeType": {
                  "type": "string",
                  "maxLength": 60,
                  "default": "",
                  "title": "Type"
                },
                "added": {
                  "type": "string",
                  "maxLength": 40,
                  "default": "",
                  "title": "Added"
                }
              }
            }
          },
          "personality": {
            "type": "object",
            "title": "Personality",
            "default": {},
            "additionalProperties": false,
            "properties": {
              "summary": {
                "type": "string",
                "maxLength": 800,
                "default": "",
                "title": "In one sentence"
              },
              "traits": {
                "type": "array",
                "default": [],
                "title": "Traits",
                "maxItems": 64,
                "items": {
                  "type": "string",
                  "maxLength": 80
                }
              },
              "values": {
                "type": "array",
                "default": [],
                "title": "Values",
                "maxItems": 64,
                "items": {
                  "type": "string",
                  "maxLength": 160
                }
              },
              "desires": {
                "type": "array",
                "default": [],
                "title": "Wants",
                "maxItems": 64,
                "items": {
                  "type": "string",
                  "maxLength": 200
                }
              },
              "fears": {
                "type": "array",
                "default": [],
                "title": "Fears",
                "maxItems": 64,
                "items": {
                  "type": "string",
                  "maxLength": 200
                }
              },
              "flaws": {
                "type": "array",
                "default": [],
                "title": "Flaws",
                "maxItems": 64,
                "items": {
                  "type": "string",
                  "maxLength": 200
                }
              },
              "quirks": {
                "type": "array",
                "default": [],
                "title": "Quirks and habits",
                "maxItems": 64,
                "items": {
                  "type": "string",
                  "maxLength": 200
                }
              },
              "humour": {
                "type": "string",
                "maxLength": 400,
                "default": "",
                "title": "Sense of humour"
              },
              "temperament": {
                "type": "string",
                "maxLength": 400,
                "default": "",
                "title": "Baseline temperament"
              },
              "moral_compass": {
                "type": "string",
                "maxLength": 600,
                "default": "",
                "title": "Moral compass"
              }
            },
            "description": "Who the character is, independent of any scene."
          },
          "speech": {
            "type": "object",
            "title": "Speech",
            "default": {},
            "additionalProperties": false,
            "properties": {
              "style": {
                "type": "string",
                "maxLength": 1200,
                "default": "",
                "title": "Speaking style"
              },
              "register": {
                "type": "string",
                "maxLength": 300,
                "default": "",
                "title": "Register",
                "description": "Formal, street, archaic, clinical..."
              },
              "vocabulary": {
                "type": "string",
                "maxLength": 600,
                "default": "",
                "title": "Vocabulary and imagery"
              },
              "accent": {
                "type": "string",
                "maxLength": 300,
                "default": "",
                "title": "Accent"
              },
              "verbal_tics": {
                "type": "array",
                "default": [],
                "title": "Verbal tics",
                "maxItems": 64,
                "items": {
                  "type": "string",
                  "maxLength": 120
                }
              },
              "catchphrases": {
                "type": "array",
                "default": [],
                "title": "Catchphrases",
                "maxItems": 64,
                "items": {
                  "type": "string",
                  "maxLength": 200
                }
              },
              "languages": {
                "type": "array",
                "default": [],
                "title": "Languages spoken",
                "maxItems": 64,
                "items": {
                  "type": "string",
                  "maxLength": 60
                }
              },
              "narration_style": {
                "type": "string",
                "maxLength": 600,
                "default": "Short actions between asterisks, then dialogue.",
                "title": "Narration style"
              },
              "example_dialogues": {
                "type": "string",
                "maxLength": 6000,
                "default": "",
                "title": "Example dialogues"
              }
            },
            "description": "How the character sounds on the page."
          },
          "background": {
            "type": "object",
            "title": "Background",
            "default": {},
            "additionalProperties": false,
            "properties": {
              "origin": {
                "type": "string",
                "maxLength": 1200,
                "default": "",
                "title": "Origin"
              },
              "story": {
                "type": "string",
                "maxLength": 8000,
                "default": "",
                "title": "Life story"
              },
              "occupation": {
                "type": "string",
                "maxLength": 400,
                "default": "",
                "title": "Occupation or role"
              },
              "skills": {
                "type": "array",
                "default": [],
                "title": "Skills",
                "maxItems": 64,
                "items": {
                  "type": "string",
                  "maxLength": 200
                }
              },
              "possessions": {
                "type": "array",
                "default": [],
                "title": "Notable possessions",
                "maxItems": 64,
                "items": {
                  "type": "string",
                  "maxLength": 200
                }
              },
              "secrets": {
                "type": "string",
                "maxLength": 2000,
                "default": "",
                "title": "Secrets",
                "description": "Known to you, not necessarily revealed in play."
              },
              "factions": {
                "type": "array",
                "default": [],
                "title": "Factions and affiliations",
                "maxItems": 64,
                "items": {
                  "type": "string",
                  "maxLength": 160
                }
              }
            },
            "description": "Where the character comes from."
          },
          "state": {
            "type": "object",
            "title": "Current state",
            "default": {},
            "additionalProperties": false,
            "properties": {
              "scenario": {
                "type": "string",
                "maxLength": 4000,
                "default": "",
                "title": "Scene in progress"
              },
              "location": {
                "type": "string",
                "maxLength": 400,
                "default": "",
                "title": "Location"
              },
              "time": {
                "type": "string",
                "maxLength": 300,
                "default": "",
                "title": "Time and date in fiction"
              },
              "mood": {
                "type": "string",
                "maxLength": 300,
                "default": "",
                "title": "Mood"
              },
              "energy": {
                "type": "string",
                "maxLength": 300,
                "default": "",
                "title": "Physical condition"
              },
              "outfit_now": {
                "type": "string",
                "maxLength": 600,
                "default": "",
                "title": "Currently wearing"
              },
              "goals": {
                "type": "array",
                "default": [],
                "title": "Immediate goals",
                "maxItems": 64,
                "items": {
                  "type": "string",
                  "maxLength": 300
                }
              },
              "tensions": {
                "type": "array",
                "default": [],
                "title": "Open tensions",
                "maxItems": 64,
                "items": {
                  "type": "string",
                  "maxLength": 300
                }
              },
              "updated": {
                "type": "string",
                "maxLength": 40,
                "default": "",
                "title": "Last updated"
              }
            },
            "description": "What changes as the story advances."
          },
          "memory": {
            "type": "object",
            "title": "Memory",
            "default": {},
            "additionalProperties": false,
            "properties": {
              "facts": {
                "type": "array",
                "default": [],
                "title": "Persistent facts",
                "maxItems": 64,
                "items": {
                  "type": "string",
                  "maxLength": 500
                },
                "description": "Always injected. Kept explicit: nothing is harvested from conversations without you applying it."
              },
              "episodes": {
                "type": "array",
                "default": [],
                "title": "Remembered episodes",
                "maxItems": 500,
                "items": {
                  "type": "object",
                  "title": "Episode",
                  "default": {},
                  "additionalProperties": false,
                  "properties": {
                    "when": {
                      "type": "string",
                      "maxLength": 80,
                      "default": "",
                      "title": "When"
                    },
                    "summary": {
                      "type": "string",
                      "maxLength": 1200,
                      "default": "",
                      "title": "What happened"
                    },
                    "weight": {
                      "type": "number",
                      "minimum": 0.0,
                      "maximum": 1.0,
                      "default": 0.5
                    },
                    "session_id": {
                      "type": "string",
                      "maxLength": 80,
                      "default": "",
                      "title": "Session"
                    },
                    "pinned": {
                      "type": "boolean",
                      "default": false
                    }
                  }
                }
              }
            },
            "description": "What the character carries between sessions."
          },
          "relationships": {
            "type": "array",
            "default": [],
            "maxItems": 200,
            "title": "Relationships",
            "items": {
              "type": "object",
              "title": "Relationship",
              "default": {},
              "additionalProperties": false,
              "properties": {
                "persona_id": {
                  "type": "string",
                  "maxLength": 80,
                  "default": "",
                  "title": "Other character"
                },
                "name": {
                  "type": "string",
                  "maxLength": 120,
                  "default": "",
                  "title": "Name as known",
                  "description": "Kept so an exported sheet still reads when the other persona is absent."
                },
                "type": {
                  "type": "string",
                  "maxLength": 80,
                  "default": "",
                  "title": "Kind of bond",
                  "description": "sibling, rival, mentor, lover, employer..."
                },
                "label": {
                  "type": "string",
                  "maxLength": 120,
                  "default": "",
                  "title": "How this character names them"
                },
                "sentiment": {
                  "type": "number",
                  "minimum": -1.0,
                  "maximum": 1.0,
                  "default": 0.0,
                  "description": "-1 hostile, 0 neutral, 1 devoted."
                },
                "trust": {
                  "type": "number",
                  "minimum": 0.0,
                  "maximum": 1.0,
                  "default": 0.5
                },
                "history": {
                  "type": "string",
                  "maxLength": 3000,
                  "default": "",
                  "title": "Shared history"
                },
                "tension": {
                  "type": "string",
                  "maxLength": 1000,
                  "default": "",
                  "title": "Current tension"
                },
                "secret": {
                  "type": "string",
                  "maxLength": 1000,
                  "default": "",
                  "title": "Kept from them"
                },
                "known": {
                  "type": "boolean",
                  "default": true,
                  "title": "They have met",
                  "description": "False for a one-sided or rumoured bond."
                }
              }
            }
          },
          "voice": {
            "type": "object",
            "title": "Voice",
            "default": {},
            "additionalProperties": false,
            "properties": {
              "enabled": {
                "type": "boolean",
                "default": false,
                "title": "Speak replies"
              },
              "voice_id": {
                "type": "string",
                "maxLength": 80,
                "default": "",
                "title": "Stable voice",
                "description": "Identifier of a stable voice in data/voices."
              },
              "backend": {
                "type": "string",
                "enum": [
                  "qwen3tts",
                  "piper",
                  "none"
                ],
                "default": "qwen3tts"
              },
              "model": {
                "type": "string",
                "maxLength": 60,
                "default": "1.7B-CustomVoice",
                "title": "Voice model"
              },
              "speaker": {
                "type": "string",
                "maxLength": 60,
                "default": "",
                "title": "Preset speaker",
                "description": "Used when no stable voice is attached."
              },
              "language": {
                "type": "string",
                "default": "Auto",
                "title": "Spoken language",
                "enum": [
                  "Auto",
                  "French",
                  "English",
                  "Spanish",
                  "German",
                  "Italian",
                  "Portuguese",
                  "Russian",
                  "Chinese",
                  "Japanese",
                  "Korean"
                ],
                "description": "The language the character's lines are written in. It wins over the language recorded on the stable voice."
              },
              "languages": {
                "type": "array",
                "default": [],
                "maxItems": 10,
                "title": "Other languages",
                "items": {
                  "type": "object",
                  "title": "Voice in one language",
                  "default": {},
                  "additionalProperties": false,
                  "properties": {
                    "language": {
                      "type": "string",
                      "enum": [
                        "French",
                        "English",
                        "Spanish",
                        "German",
                        "Italian",
                        "Portuguese",
                        "Russian",
                        "Chinese",
                        "Japanese",
                        "Korean"
                      ],
                      "default": "English",
                      "title": "Language"
                    },
                    "source": {
                      "type": "string",
                      "enum": [
                        "same",
                        "voice",
                        "design",
                        "preset"
                      ],
                      "default": "same",
                      "title": "Voice used",
                      "description": "same: the character's own voice speaking this language. voice: another stable voice, typically captured from a take in this language. design: a voice invented from a description. preset: one of the preset speakers."
                    },
                    "accent": {
                      "type": "string",
                      "enum": [
                        "keep",
                        "native"
                      ],
                      "default": "keep",
                      "title": "Accent",
                      "description": "With the same voice. keep: the character keeps the accent of its own take. native: only the timbre is kept and the words are pronounced the way the model pronounces this language."
                    },
                    "voice_id": {
                      "type": "string",
                      "maxLength": 80,
                      "default": "",
                      "title": "Stable voice for this language"
                    },
                    "description": {
                      "type": "string",
                      "maxLength": 800,
                      "default": "",
                      "title": "Voice to invent for this language"
                    },
                    "speaker": {
                      "type": "string",
                      "maxLength": 60,
                      "default": "Ryan",
                      "title": "Preset speaker"
                    },
                    "instruction": {
                      "type": "string",
                      "maxLength": 1000,
                      "default": "",
                      "title": "Direction for this language",
                      "description": "Read by invented and preset voices. A cloned voice reproduces its take and takes no written direction."
                    },
                    "seed": {
                      "type": "integer",
                      "minimum": -1,
                      "maximum": 2147483647,
                      "default": -1,
                      "title": "Seed",
                      "description": "-1 keeps the seed of the main voice."
                    }
                  },
                  "description": "One entry per language the character should speak differently."
                },
                "description": "How the character sounds when a translated line is spoken. A language with no entry uses the same voice, accent kept."
              },
              "speed": {
                "type": "number",
                "minimum": 0.25,
                "maximum": 4.0,
                "default": 1.0
              },
              "pitch": {
                "type": "number",
                "minimum": -12.0,
                "maximum": 12.0,
                "default": 0.0
              },
              "instruction": {
                "type": "string",
                "maxLength": 2000,
                "default": "",
                "title": "Standing voice direction",
                "description": "How this character always sounds, independent of the line."
              },
              "description": {
                "type": "string",
                "maxLength": 800,
                "default": "",
                "title": "Voice to invent",
                "description": "A written portrait of the voice — age, grain, pace, accent. With no stable voice attached, this is what VoiceDesign builds from, which is also the easiest way to produce the first take a stable voice is then captured from."
              },
              "use_persona_style": {
                "type": "boolean",
                "default": true,
                "title": "Derive delivery from the persona and the scene"
              },
              "annotations": {
                "type": "boolean",
                "default": true,
                "title": "Let the model write [tone:] and [pause:] marks"
              },
              "speak_narration": {
                "type": "boolean",
                "default": false,
                "title": "Also speak *stage directions*",
                "description": "Off by default: the voice says the dialogue, not the narration around it. The scene directive is never spoken."
              },
              "delivery": {
                "type": "string",
                "enum": [
                  "paragraphs",
                  "complete"
                ],
                "default": "paragraphs",
                "description": "Play paragraph by paragraph, or wait for the whole take."
              }
            },
            "description": "How this character is heard."
          },
          "media": {
            "type": "object",
            "title": "Visual direction",
            "default": {},
            "additionalProperties": false,
            "properties": {
              "enabled": {
                "type": "boolean",
                "default": false,
                "title": "Ask for a scene description with each reply"
              },
              "mode": {
                "type": "string",
                "enum": [
                  "director",
                  "inline"
                ],
                "default": "director",
                "title": "How the description is produced",
                "description": "director: a second, constrained pass reads the reply and emits the directive, so the JSON is always valid and never leaks into the dialogue. inline: the same model is asked for both at once — one generation instead of two, but small models often skip it."
              },
              "detail": {
                "type": "string",
                "enum": [
                  "minimal",
                  "standard",
                  "full"
                ],
                "default": "standard"
              },
              "director_model": {
                "type": "string",
                "maxLength": 60,
                "default": "",
                "title": "Model used for the description",
