{
  "id": "speak_batch_file",
  "name": "Speak a batch task from files",
  "description": "speak_batch, with files: the list read from file (a script .txt, a CSV .csv/.tsv or a JSON list .json; text or items still work), and personas, the characters the task brings — bundles exported by PersonaRP with their recordings (sheet, world, stable voices, the per-language ones included). They are copied into the task folder (personnages/) and never into the library, and are looked up before the library; use_library false keeps the task to its own characters. The folder holds the list as given (source.*), the batch as understood (lot.json), one WAV per line in voix/, and resultats.json / resultats.csv. The lines are generated many at a time in one copy of the voice model; with batch_size 0 the number follows the free VRAM, and a batch that does not fit is halved and tried again, so a large GPU is used to the full. A speaker is found by identifier, name, alias or a part of its name no other character has; voice names a stable voice instead, or on top of the character. A line that cannot be spoken is reported and the batch goes on. dry_run checks the list — speakers, voices, languages — before paying for it.",
  "inputSchema": {
    "type": "object",
    "additionalProperties": false,
    "properties": {
      "file": {
        "type": "string",
        "default": "",
        "title": "Batch file",
        "maxLength": 1000,
        "x-cy-kind": "File"
      },
      "personas": {
        "type": "array",
        "maxItems": 64,
        "title": "Characters of the task",
        "items": {
          "type": "string",
